const {chromium}=require(process.env.ADC_PLAYWRIGHT_MODULE || 'playwright');
const path=require('node:path');
const fs=require('node:fs');
const output=path.resolve(__dirname,'../../../../work');
fs.mkdirSync(output,{recursive:true,mode:0o700});
const [base,doc]=process.argv.slice(2);
(async()=>{
 const browser=await chromium.launch({headless:true});
 try{
 const page=await browser.newPage({viewport:{width:1440,height:1000}});
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto(base+'/login');
 await page.getByLabel('Username',{exact:true}).fill('fixture');
 await page.getByLabel('Password',{exact:true}).fill('ui-fixture-password');
 await page.getByRole('button',{name:'Sign in'}).click();
 await page.getByRole('heading',{name:'Needs your input',exact:true}).waitFor();
 await page.getByRole('button',{name:'Assign work'}).click();
 await page.getByLabel('Title',{exact:true}).fill('In-progress outcome');
 await page.request.get(base+'/fixture-state');
 await page.getByText('Updated fixture assignment',{exact:true}).waitFor();
 if(await page.getByLabel('Title',{exact:true}).inputValue()!=='In-progress outcome')throw new Error('Work overview update erased the assignment form');
 await page.getByRole('button',{name:'Close',exact:true}).click();
 await page.getByRole('link',{name:/Which website section should lead/}).click();
 await page.getByRole('link',{name:'← Older activity',exact:true}).click();
 await page.getByText('Historical fixture event 000',{exact:true}).waitFor();
 await page.getByRole('link',{name:'Return to live activity →',exact:true}).click();
 const group=page.locator('.tool-group').first();
 if(await group.getAttribute('open')!==null)throw new Error('Tool activity starts expanded');
 await group.getByText('1 failed',{exact:true}).waitFor();
 const agent=page.locator('#runlist .run-agent').first();
 if(await agent.textContent()!=='Supervisor')throw new Error('Agent name missing from rail');
 const order=await agent.evaluate(el=>Boolean(el.compareDocumentPosition(el.parentElement.querySelector('.run-model'))&Node.DOCUMENT_POSITION_FOLLOWING));
 if(!order)throw new Error('Agent name does not precede model');
 const bounded=await page.locator('#timeline').evaluate(el=>el.clientHeight<=innerHeight*.61 && el.scrollHeight>el.clientHeight);
 if(!bounded)throw new Error('Activity does not scroll within a bounded pane');
 if(await page.evaluate(()=>document.documentElement.scrollHeight>2200))throw new Error('Long activity expands the whole page');
 await group.locator('summary').click();
 const groupID=await group.getAttribute('id');
 if(await page.locator('#tool-evidence-panel').getAttribute('open')!==null)throw new Error('Tool evidence should start collapsed');
 const railScroll=await page.locator('.task-aside').evaluate(el=>getComputedStyle(el).overflowY);
 if(railScroll!=='visible')throw new Error('Whole rail still scrolls');
 await page.locator('#tool-evidence-panel > summary').click();
 await page.locator('summary').filter({hasText:'run_repository_checks'}).click();
 await page.getByText('All fixture checks passed',{exact:true}).waitFor();
 await page.getByLabel('Your decision',{exact:true}).fill('Lead with currently shipping products.');
 await page.request.get(base+'/fixture-event');
 await page.getByText('A new evidence source is available.',{exact:true}).waitFor();
 if(await page.locator('#tool-evidence-panel').getAttribute('open')===null)throw new Error('Live update closed tool evidence panel');
 if(await page.locator('#'+groupID).getAttribute('open')===null)throw new Error('Live update collapsed inspected tool activity');
 if(await page.getByLabel('Your decision',{exact:true}).inputValue()!=='Lead with currently shipping products.')throw new Error('SSE update lost in-progress decision');
 await page.locator('#'+groupID+' > summary').click();
 await page.locator('#timeline').evaluate(el=>el.scrollTop=0);
 await page.screenshot({path:path.join(output,'ui-task-desktop.png'),fullPage:true});
 await page.setViewportSize({width:390,height:844});
 if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw new Error('Phone activity overflows horizontally');
 if(await page.locator('#timeline').evaluate(el=>el.clientHeight>innerHeight*.56))throw new Error('Phone activity is unbounded');
 await page.screenshot({path:path.join(output,'ui-task-mobile.png'),fullPage:true});
 await page.setViewportSize({width:1440,height:1000});
 await page.getByRole('button',{name:'Send decision'}).click();
 await page.goto(base+`/task?id=task&org=org&doc=${doc}`);
 await page.getByRole('combobox',{name:'Document revision'}).selectOption('1');
 await page.locator('#document').getByText('Snow and Floe are shipping today.',{exact:true}).waitFor();
 await page.setViewportSize({width:390,height:844});
 await page.evaluate(()=>{const p=document.querySelector('#document p');const range=document.createRange();range.selectNodeContents(p);const s=window.getSelection();s.removeAllRanges();s.addRange(range);document.dispatchEvent(new Event('selectionchange'));});
 await page.getByRole('button',{name:'Discuss selection'}).click();
 if(await page.locator('#context-revision').inputValue()!=='1')throw new Error('Selection revision lost');
 await page.getByLabel('Message or steering').fill('Why did you change this paragraph?');
 await page.screenshot({path:path.join(output,'ui-document-mobile.png'),fullPage:true});
 if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw new Error('Phone document overflows');
 await page.getByRole('button',{name:'Send ↑',exact:true}).click();
 await page.getByText(/Context: document Website evidence.*revision 1/).first().waitFor();
 await page.getByRole('link',{name:'Organization settings',exact:true}).click();
 await page.getByLabel('Current password',{exact:true}).fill('ui-fixture-password');
 await page.getByLabel('New password',{exact:true}).fill('new-ui-fixture-password');
 await page.getByLabel('Confirm new password',{exact:true}).fill('new-ui-fixture-password');
 await page.getByRole('button',{name:'Change password',exact:true}).click();
 await page.getByRole('button',{name:'Switch color theme',exact:true}).click();
 const headerFits=await page.evaluate(()=>document.querySelector('#theme').getBoundingClientRect().bottom <= document.querySelector('.topbar').getBoundingClientRect().bottom + 1);
 if(!headerFits)throw new Error('Phone header controls overlap the content');
 await page.screenshot({path:path.join(output,'ui-settings-mobile-dark.png'),fullPage:true});
 if(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw new Error('Phone settings overflow');
 await page.getByRole('button',{name:'Sign out',exact:true}).click();
 await page.getByLabel('Username',{exact:true}).fill('fixture');
 await page.getByLabel('Password',{exact:true}).fill('new-ui-fixture-password');
 await page.getByRole('button',{name:'Sign in'}).click();
 await page.getByRole('heading',{name:'Work in motion.'}).waitFor();
 if(errors.length)throw new Error(errors.join('\n'));
 console.log(JSON.stringify({liveOverview:true,collapsedToolsPreserved:true,agentNameBeforeModel:true,boundedActivity:true,independentRailSections:true,toolEvidenceCollapsedByDefault:true,passwordChangedAndLoginVerified:true,decisionInbox:true,olderActivityAccessible:true,toolEvidenceInspectable:true,decisionPreservedAcrossLiveUpdate:true,decisionSaved:true,historicalSelectionSent:true,mobileOverflow:false,browserErrors:errors}));
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1});
